import math

def can_be_product_of_two_squares(n):
    if n < 0:
        return False
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
    if n > 2:
        factors[n] = factors.get(n, 0) + 1
    for factor, exp in factors.items():
        if factor % 4 == 3 and exp % 2 != 0:
            return False
    return True
